import os,sys,collections
A='/home/deck/alpha'
out=open('/tmp/judge-tk031.txt','w')
for m in sys.argv[1:]:
    A65=f'{A}/epochs/e-{m}/b5'; A11=f'{A}/epochs11/e-{m}/b5'; D=f'{A}/merged/e-{m}/b5'
    c=collections.Counter(); ex=collections.defaultdict(list); names=collections.Counter()
    for dp,_,fs in os.walk(A11):
        for fn in fs:
            if fn.endswith('.log'): continue
            p11=os.path.join(dp,fn); rel=os.path.relpath(p11,A11)
            p65=os.path.join(A65,rel); pm=os.path.join(D,rel)
            names[fn]+=1; c['files']+=1
            if not os.path.exists(p65): c['no65']+=1; continue
            l11=open(p11,'rb').read().split(b'\n'); b65=open(p65,'rb').read(); l65=b65.split(b'\n')
            if b65 and not b65.endswith(b'\n'): c['65_no_nl']+=1; ex['65_no_nl'].append(rel)
            h11=[x for x in l11 if x.startswith(b'#')]; h65=[x for x in l65 if x.startswith(b'#')]
            if [x.replace(b'study/ax/D20',b'study/approaches/D20') for x in h11]!=h65: c['hdr_diff_after_subst']+=1; ex['hdr'].append(rel)
            n11=[x for x in l11 if not x.startswith(b'#')]; n65=[x for x in l65 if not x.startswith(b'#')]
            if n11 and n65 and n11[0]!=n65[0]: c['colhdr_diff']+=1; ex['col'].append(rel)
            cols=n65[0].split(b',') if n65 else []
            if b'symbol' in cols:
                i=cols.index(b'symbol')
                s65={r.split(b',')[i] for r in n65[1:] if r}; s11={r.split(b',')[i] for r in n11[1:] if r}
                if s65&s11: c['dup_sym']+=1; ex['dup'].append(rel)
            else: c['nosym:'+fn]+=1
            bm=open(pm,'rb').read()
            exp=b65+b''.join(x+b'\n' for x in n11[1:] if x)  # body lines
            if bm!=exp: c['merged_mismatch']+=1; ex['mm'].append(rel)
    print(m,dict(c),{k:v[:3] for k,v in ex.items()},dict(names.most_common(8)),file=out,flush=True)
EOF
